package org.firstinspires.ftc.teamcode.opmodes.auto.generated;

import com.pedropathing.api.Paths;
import com.pedropathing.api.PoseFactory;
import com.pedropathing.ivy.Command;
import com.pedropathing.math.Pose;
import com.pedropathing.paths.Path;
import com.pedropathing.paths.interpolator.Interpolator;

import org.firstinspires.ftc.teamcode.autokit.AutoKit;
import org.firstinspires.ftc.teamcode.autokit.AutoOption;

/**
 * Generated by the Auto Builder from r-solo-turret.pp. Do not edit: change the .pp and export again.
 */
public final class RSoloTurretAuto {

    private RSoloTurretAuto() {}

    /** The .pp file this was generated from. */
    public static final String SOURCE = "r-solo-turret.pp";

    /** When the .pp was saved, Michigan time (empty if unknown); the OpMode's name on the Driver Station ends with it. */
    public static final String SAVED = "11-17|12:25PM";

    /** Registered robot commands this Auto uses; checked when the OpMode initialises. */
    public static final String[] COMMANDS = {"LaunchAll", "PickFlower", "SpinUp"};

    /** Registered robot triggers this Auto uses; checked when the OpMode initialises. */
    public static final String[] TRIGGERS = {};

    /** The alliance the Auto was drawn for ("RED" or "BLUE"); the other alliance runs it rotated half a turn about the field centre. */
    public static final String DRAWN_FOR = "RED";

    /** Drawn for a turret that aims: the robot tracks our CELL for the whole Auto and its launches wait for the turret, not the chassis. A robot whose turret is locked does not run it. */
    public static final boolean TURRET_AIMS = true;

    /** What the drive team may change during INIT, on gamepad 1's D-pad; nothing changed, the Auto runs as drawn. */
    public static final AutoOption[] OPTIONS = {};

    /** Where the robot starts, for the given alliance. */
    public static Pose startPose(boolean rotated) {
        return poses(rotated).of(55.6, 7.7, 90);
    }

    private static PoseFactory poses(boolean rotated) {
        return rotated ? PoseFactory.degrees().mirrorAroundPoint(70.75, 70.75) : PoseFactory.degrees();
    }

    /** Builds the whole Auto. Call once, at init; schedule the result at start. */
    public static Command build(AutoKit kit, boolean rotated) {
        PoseFactory p = poses(rotated);

        // Named points (x, y in inches, heading in degrees, Pedro field frame).
        Pose rightStart = p.of(55.6, 7.7, 90);
        Pose wallFlowerStaging = p.of(23.1, 47.2, 180);
        Pose leftTurretFire = p.of(38, 126, 90);
        Pose scoringFlowerStaging = p.of(47.2, 119.3, 90);
        Pose rightPark = p.of(14.5, 98.7, 0);

        // Other poses the paths need (control points, unnamed endpoints).
        Pose wallLaneNorthToLeftTurretFireControl1 = p.of(26, 60, 0);
        Pose wallLaneNorthToLeftTurretFireControl2 = p.of(33, 92, 0);
        Pose wallLaneNorthToLeftTurretFireControl3 = p.of(35, 104, 0);
        Pose wallLaneNorthToLeftTurretFireSegment1Start = p.of(38, 126, 180);
        Pose leftTurretFireParkControl1 = p.of(30, 112, 0);
        Pose leftTurretFireParkControl2 = p.of(24, 99, 0);
        Pose scoringFlowerStagingParkControl1 = p.of(40, 96, 0);

        // Paths, written as the stock Visualizer export writes them.
        Path toWallFlowerStaging = Paths.line(rightStart, wallFlowerStaging).linear(rightStart, wallFlowerStaging);
        Path wallFlowerStagingPark = Paths.line(wallFlowerStaging, rightPark).linear(wallFlowerStaging, rightPark);
        Path wallLaneNorthToLeftTurretFire = Paths.curve(wallFlowerStaging, wallLaneNorthToLeftTurretFireControl1, wallLaneNorthToLeftTurretFireControl2, wallLaneNorthToLeftTurretFireControl3, leftTurretFire).heading(Interpolator.piecewise().until(0.2, Interpolator.linear(wallLaneNorthToLeftTurretFireSegment1Start, leftTurretFire)).until(1, Interpolator.constant(leftTurretFire)));
        Path leftTurretFirePark = Paths.curve(leftTurretFire, leftTurretFireParkControl1, leftTurretFireParkControl2, rightPark).linear(leftTurretFire, rightPark);
        Path hopToScoringFlowerStaging = Paths.line(leftTurretFire, scoringFlowerStaging).constant(scoringFlowerStaging);
        Path scoringFlowerStagingPark = Paths.curve(scoringFlowerStaging, scoringFlowerStagingParkControl1, rightPark).linear(scoringFlowerStaging, rightPark);
        Path hopBackToLeftTurretFire = Paths.line(scoringFlowerStaging, leftTurretFire).constant(leftTurretFire);

        return kit.sequence(
                kit.guarded("Auto", leftTurretFirePark, 1.8,
                        kit.command("SpinUp"),
                        kit.command("LaunchAll"),
                        kit.path("to WALL_FLOWER_STAGING", toWallFlowerStaging, 2.1, wallFlowerStagingPark, 2.1),
                        kit.command("PickFlower", 4.5),
                        kit.path("wall lane north to LEFT_TURRET_FIRE", wallLaneNorthToLeftTurretFire, 2.7, leftTurretFirePark, 1.8),
                        kit.command("LaunchAll"),
                        kit.path("hop to SCORING_FLOWER_STAGING", hopToScoringFlowerStaging, 1, scoringFlowerStagingPark, 1.9),
                        kit.command("PickFlower", 4.5),
                        kit.path("hop back to LEFT_TURRET_FIRE", hopBackToLeftTurretFire, 1, leftTurretFirePark, 1.8),
                        kit.command("LaunchAll"),
                        kit.path("LEFT_TURRET_FIRE park", leftTurretFirePark, 1.8)));
    }
}
